\label{lem:intermediate-algebra}
Let $(M^n,g)$ satisfy $\operatorname{Ric}_k\geq0$ for some $1\leq k\leq n-2$. Then $\operatorname{Ric}\geq0$. Moreover, for every orthonormal pair $X,Y$,
\begin{equation}\label{eq:sectional-lower-bound}
K(X,Y)\geq-\frac{k-1}{n-1-k}\operatorname{Ric}(X,X),
\end{equation}
where the right-hand side is understood to be $0$ when $k=1$.

\label{cor:null-jacobi}
Under the assumptions of Lemma~\ref{lem:intermediate-algebra}, if $V\in\ker\operatorname{Ric}$, then
\begin{equation}\label{eq:null-sectional}
K(V,X)=0
\end{equation}
for every $X\perp V$. Equivalently,
\begin{equation}\label{eq:null-jacobi-tensor}
R(V,\cdot,V,\cdot)\equiv0.
\end{equation}

\label{prop:subtrace-inequality}
For every $1\leq\ell\leq n$, the function $\sigma_\ell=\lambda_1+\cdots+\lambda_\ell$ satisfies
\begin{equation}\label{eq:main-subtrace}
\Delta\sigma_\ell
\leq
\frac{n-2}{n-1-k}R\,\sigma_\ell
\end{equation}
in the viscosity sense.

\label{lem:codazzi-warp}
For the metric~\eqref{eq:double-warp}, the Ricci tensor is Codazzi if and only if
\begin{align}
\rho_1'&=a(\rho_0-\rho_1),
\label{eq:codazzi-rho1}\\
\rho_3'&=b(\rho_0-\rho_3).
\label{eq:codazzi-rho3}
\end{align}
Consequently,~\eqref{eq:codazzi-rho1}--\eqref{eq:codazzi-rho3} are equivalent to $g$ having harmonic curvature.

\label{prop:soliton-subtrace}
The lower Ricci subtrace $\sigma_\ell$ satisfies
\begin{equation}\label{eq:soliton-subtrace}
\Delta_f\sigma_\ell
\leq
\bigl(2\lambda+2c_{n,k}R\bigr)\sigma_\ell
\end{equation}
in the viscosity sense.

\label{prop:soliton-nullity-parallel}
Under the assumptions of Theorem~\ref{thm:mainB}, the
distribution $\mathcal N=\ker\operatorname{Ric}$ is parallel.
